import React, { createContext, useContext, useState, FC, ReactNode } from 'react';
import { IDoctor } from "../../intefaces/doctorInterfaces";

// Замість імпорту JSON, створіть масив з початковими даними
const initialDoctorsData: IDoctor[] = [
  // Додайте кілька прикладів лікарів тут
  // Наприклад:
  // { doctor_id: 1, name: "Dr. Smith", specialization: "Cardiology", price: 100, rating: 4.5, country: "USA" },
  // { doctor_id: 2, name: "Dr. Johnson", specialization: "Pediatrics", price: 80, rating: 4.2, country: "Canada" },
];

const flattenedDoctorsData: IDoctor[] = initialDoctorsData;

export interface SearchOptions {
  term: string;
  price: number | null;
  rating: number | null;
  country: string;
  sort: string;
}

interface DoctorsContextProps {
  doctors: IDoctor[];
  setDoctors: React.Dispatch<React.SetStateAction<IDoctor[]>>;
  searchOptions: SearchOptions;
  setSearchOptions: React.Dispatch<React.SetStateAction<SearchOptions>>;
}

const DoctorsContext = createContext<DoctorsContextProps | undefined>(undefined);

export const useDoctors = () => {
  const context = useContext(DoctorsContext);
  if (!context) {
    throw new Error('useDoctors must be used within a DoctorsProvider');
  }
  return context;
};

export const DoctorsProvider: FC<{ children: ReactNode }> = ({ children }) => {
  const [doctors, setDoctors] = useState<IDoctor[]>(flattenedDoctorsData);
  const [searchOptions, setSearchOptions] = useState<SearchOptions>({
    term: '',
    price: null,
    rating: null,
    country: '',
    sort: ''
  });

  return (
    <DoctorsContext.Provider value={{ doctors, setDoctors, searchOptions, setSearchOptions }}>
      {children}
    </DoctorsContext.Provider>
  );
};

export { DoctorsContext };
